window.__GAME_HTML_CHUNKS=window.__GAME_HTML_CHUNKS||[];window.__GAME_HTML_CHUNKS.push("\" alt=\"Tinto Suave\"><div class=\"bgBottleName\">Tinto Suave</div></div>\n    </div>\n\n    <main id=\"boardWrap\">\n      <div id=\"board\" aria-label=\"Tabuleiro\"></div>\n    </main>\n  </section>\n\n  <div id=\"pourStream\"></div>\n  <div id=\"toast\"></div>\n\n  <div class=\"modal\" id=\"nameModal\"><div class=\"panel\"><h2>NOME DO JOGADOR</h2><p>Digite seu nome antes de iniciar a partida.</p><input class=\"nameInput\" id=\"playerNameInput\" maxlength=\"24\" autocomplete=\"off\" placeholder=\"Seu nome\"><div class=\"nameError\" id=\"nameError\"></div><div class=\"panelBtns\"><button class=\"panelBtn green\" id=\"confirmNameBtn\">INICIAR</button><button class=\"panelBtn\" id=\"cancelNameBtn\">VOLTAR</button></div></div></div>\n  <div class=\"modal\" id=\"pauseModal\"><div class=\"panel\"><h2>Jogo pausado</h2><p>Seu progresso está preservado.</p><div class=\"panelBtns\"><button class=\"panelBtn green\" id=\"resumeBtn\">RETORNAR</button><button class=\"panelBtn\" id=\"pauseResetBtn\">REINICIAR</button><button class=\"panelBtn\" id=\"pauseHomeBtn\">CAPA</button></div></div></div>\n  <div class=\"modal\" id=\"helpModal\"><div class=\"panel\"><h2>COMO JOGAR</h2><p>Toque em uma taça e depois em outra para derramar apenas o líquido do topo.</p><p>Você pode derramar para qualquer taça que tenha espaço. Se houver 2 ou mais camadas seguidas da mesma cor no topo, todas elas são derramadas juntas para agilizar a jogada.</p><p>Objetivo: deixar cada taça com uma cor só e exatamente na posição da garrafa correspondente acima.</p><div class=\"panelBtns\"><button class=\"panelBtn green\" id=\"closeHelpBtn\">ENTENDI</button></div></div></div>\n  <div class=\"modal\" id=\"rankingModal\"><div class=\"panel\"><h2>RANKING</h2><p>Ranking por menor número de movimentos. Em caso de empate, vence o menor tempo. Cada nova rodada embaralha os líquidos.</p><div class=\"rankList\" id=\"rankingList\"></div><div class=\"panelBtns\"><button class=\"panelBtn green\" id=\"closeRankingBtn\">FECHAR</button><button class=\"panelBtn\" id=\"clearRankingBtn\">LIMPAR</button></div></div></div>\n  <div class=\"modal\" id=\"winModal\"><div class=\"panel\"><div class=\"big\">🏆</div><h2>PARABÉNS!</h2><p>Parabéns! Você completou o desafio!</p><p><b id=\"finalPlayer\">Jogador</b>, conclusão em <b id=\"finalMoves\">0</b> movimentos, no tempo de <b id=\"finalTime\">00:00</b>.</p><div class=\"panelBtns\"><button class=\"panelBtn green\" id=\"playAgainBtn\">JOGAR NOVAMENTE</button><button class=\"panelBtn\" id=\"winHomeBtn\">CAPA</button></div></div></div>\n  <div class=\"modal\" id=\"loseModal\"><div class=\"panel\"><div class=\"big\">⏰</div><h2>QUE PENA!</h2><p>Que pena! O tempo acabou.</p><p><b id=\"losePlayer\">Jogador</b>, você fez <b id=\"loseMoves\">0</b> movimentos em <b id=\"loseTime\">02:00</b>.</p><div class=\"panelBtns\"><button class=\"panelBtn green\" id=\"loseAgainBtn\">TENTAR NOVAMENTE</button><button class=\"panelBtn\" id=\"loseHomeBtn\">CAPA</button></div></div></div>\n</div>\n\n<script>\n(() => {\n\n  // V46: detecção dinâmica do perfil de tela/dispositivo.\n  function applyDeviceProfile(){\n    const w = Math.max(document.documentElement.clientWidth || 0, window.innerWidth || 0);\n    const h = Math.max(document.documentElement.clientHeight || 0, window.innerHeight || 0);\n    const shortSide = Math.min(w,h);\n    const longSide = Math.max(w,h);\n    const touch = (navigator.maxTouchPoints || 0) > 0 || matchMedia('(pointer:coarse)').matches;\n    let device;\n    if (shortSide < 600 || (touch && shortSide < 700)) {\n      device = 'phone';\n    } else if (touch && (shortSide < 1000 || longSide < 1400)) {\n      device = 'tablet';\n    } else if (!touch && (h <= 950 || w <= 1680)) {\n      device = 'laptop';\n    } else {\n      device = 'desktop';\n    }\n    document.documentElement.dataset.device = device;\n    document.documentElement.style.setProperty('--safe-vh', `${h}px`);\n  }\n  applyDeviceProfile();\n  window.addEventListener('resize', applyDeviceProfile, {passive:true});\n  window.addEventListener('orientationchange', ()=>setTimeout(applyDeviceProfile,120), {passive:true});\n\n\n  // V47: Auto Fit de verdade para PC/notebook.\n  // Prioriza o tipo de ponteiro e o formato da tela, então um notebook\n  // continua sendo tratado como computador mesmo com zoom alto no Chrome\n  // ou escala aumentada no Windows.\n  function applyV47AutoFit(){\n    const root = document.documentElement;\n    const vv = window.visualViewport;\n    const w = Math.max(1, Math.round((vv && vv.width) || window.innerWidth || root.clientWidth || 1));\n    const h = Math.max(1, Math.round((vv && vv.height) || window.innerHeight || root.clientHeight || 1));\n\n    const fine = window.matchMedia && matchMedia('(pointer:fine)').matches;\n    const coarse = window.matchMedia && matchMedia('(pointer:coarse)').matches;\n    const landscape = w > h;\n\n    const sw = Math.max(\n      Number(screen && screen.availWidth) || 0,\n      Number(screen && screen.width) || 0,\n      w\n    );\n    const sh = Math.max(\n      Number(screen && screen.availHeight) || 0,\n      Number(screen && screen.height) || 0,\n      h\n    );\n\n    // Um PC pode ter viewport CSS pequeno por causa do zoom.\n    // Por isso não usamos \"w < 600 = celular\" como regra principal.\n    const looksLikeComputer =\n      landscape &&\n      (\n        fine ||\n        (!coarse && (sw >= 800 || w >= 650)) ||\n        (sw >= 1000 && sh >= 600)\n      );\n\n    let profile;\n    if (looksLikeComputer) {\n      profile = 'computer';\n      root.dataset.device = 'laptop';\n    } else if (Math.min(w,h) < 600) {\n      profile = 'phone';\n      root.dataset.device = 'phone';\n    } else {\n      profile = 'tablet';\n      root.dataset.device = 'tablet';\n    }\n\n    root.dataset.fitProfile = profile;\n    root.style.setProperty('--safe-vh', `${h}px`);\n\n    if(profile !== 'computer') return;\n\n    const clamp = (min, value, max) => Math.max(min, Math.min(max, value));\n    const px = n => `${Math.round(n * 10) / 10}px`;\n\n    // Estes valores acompanham a ALTURA útil do navegador.\n    // Se o Chrome estiver ampliado, o viewport CSS diminui e o jogo\n    // também diminui automaticamente, compensando o zoom.\n    const round       = clamp(22, h * 0.050, 40);\n    const roundFont   = clamp(12, h * 0.026, 19);\n    const brand       = clamp(10, h * 0.025, 19);\n    const subtitle    = clamp(6.5, h * 0.0125, 9.5);\n    const badge       = clamp(6.5, h * 0.0115, 9);\n    const infoH       = clamp(26, h * 0.062, 48);\n    const label       = clamp(6.5, h * 0.0115, 9);\n    const value       = clamp(11, h * 0.0215, 17);\n    const small       = clamp(6, h * 0.0105, 8.5);\n\n    const glassW      = clamp(20, h * 0.068, 52);\n    const bowlH       = clamp(44, h * 0.178, 94);\n    const stemH       = clamp(22, h * 0.047, 36);\n    const baseOffset  = clamp(19, h * 0.041, 32);\n    const baseH       = clamp(7, h * 0.014, 12);\n    const slotH       = bowlH + clamp(30, h * 0.054, 44);\n\n    const bottleTop   = clamp(52, h * 0.148, 120);\n    const bottleH     = clamp(82, h * 0.305, 245);\n    const bottleSlotH = bottleH + clamp(8, h * 0.018, 14);\n    const bottleName  = clamp(8, h * 0.021, 16);\n\n    const boardW      = clamp(300, w * 0.50, 580);\n    const bottleLineW = clamp(320, w * 0.58, 760);\n    const topMax      = clamp(320, w * 0.54, 680);\n    const infoMax     = topMax;\n\n    const boardGapX   = clamp(3, w * 0.0045, 8);\n    const boardGapY   = clamp(3, h * 0.009, 7);\n    const gapUI       = clamp(3, w * 0.004, 7);\n\n    const topPad      = clamp(2, h * 0.007, 6);\n    const playerTop   = topPad + round + clamp(1, h * 0.004, 3);\n    const infoMT      = clamp(2, h * 0.006, 5);\n    const boardBottom = clamp(4, h * 0.015, 12);\n    const toastTop    = clamp(64, h * 0.145, 118);\n    const cardRadius  = clamp(8, h * 0.018, 14);\n\n    root.dataset.fitDensity = h < 430 ? 'micro' : (h < 620 ? 'compact' : 'normal');\n\n    const vars = {\n      '--v47-round': round,\n      '--v47-round-font': roundFont,\n      '--v47-brand': brand,\n      '--v47-subtitle': subtitle,\n      '--v47-badge': badge,\n      '--v47-info-h': infoH,\n      '--v47-label': label,\n      '--v47-value': value,\n      '--v47-small': small,\n      '--v47-glass-w': glassW,\n      '--v47-bowl-h': bowlH,\n      '--v47-stem-h': stemH,\n      '--v47-base-offset': baseOffset,\n      '--v47-base-h': baseH,\n      '--v47-slot-h': slotH,\n      '--v47-bottle-top': bottleTop,\n      '--v47-bottle-h': bottleH,\n      '--v47-bottle-slot-h': bottleSlotH,\n      '--v47-bottle-name': bottleName,\n      '--v47-board-w': boardW,\n      '--v47-bottle-line-w': bottleLineW,\n      '--v47-top-max': topMax,\n      '--v47-info-max': infoMax,\n      '--v47-board-gap-x': boardGapX,\n      '--v47-board-gap-y': boardGapY,\n      '--v47-gap-ui': gapUI,\n      '--v47-top-pad': topPad,\n      '--v47-player-top': playerTop,\n      '--v47-info-mt': infoMT,\n      '--v47-board-bottom': boardBottom,\n      '--v47-toast-top': toastTop,\n      '--v47-card-radius': cardRadius,\n      '--v47-bottle-name-bottom': -clamp(3, h * 0.008, 7)\n    };\n\n    for (const [name, value] of Object.entries(vars)){\n      root.style.setProperty(name, px(value));\n    }\n  }\n\n  applyV47AutoFit();\n  window.addEventListener('resize', applyV47AutoFit, {passive:true});\n  window.addEventListener('orientationchange', ()=>setTimeout(applyV47AutoFit, 100), {passive:true});\n  if (window.visualViewport){\n    visualViewport.addEventListener('resize', applyV47AutoFit, {passive:true});\n  }\n\n\n\n  const CAPACITY = 5;\n  const GOAL_COUNT = 4;\n  const TARGETS = ['yellow','purple','pink','green','red'];\n  const BOTTLE_NAMES = ['Branco Seco','Tinto Seco','Rosé Suave','Branco Suave','Tinto Suave'];\n  // Cada rodada começa com as 5 taças contendo líquido.\n  // Cada taça tem espaço para mais 1 camada, permitindo a movimentação.\n  const COLOR_POOL = TARGETS.flatMap(c=>Array(GOAL_COUNT).fill(c));\n  const COLOR_HEX = {\n    yellow:'#e5bf3d', purple:'#8f39d6', pink:'#e76bdf', green:'#21a946', red:'#da3831'\n  };\n\n  const TOTAL_TIME = 120;\n  let initialState = [], state = [], selected = null, history = [], moves = 0, busy = false, paused = false, elapsed = 0, timeLeft = TOTAL_TIME, timerId = null, playerName = '', gameOver = false, lastTickWarn = null;\n  const board = document.getElementById('board');\n  const movesEl = document.getElementById('moves');\n  const timeEl = document.getElementById('timeDisplay');\n  const rankingHint = document.getElementById('rankingHint');\n  const playerBadge = document.getElementById('playerBadge');\n  const playerNameInput = document.getElementById('playerNameInput');\n  const nameError = document.getElementById('nameError');\n  const stream = document.getElementById('pourStream');\n  const toast = document.getElementById('toast');\n  const undoTopBtn = document.getElementById('undoTopBtn');\n  const cover = document.getElementById('cover');\n  const game = document.getElementById('game');\n  const RANK_KEY = 'ogaucho_tacas_ranking_v2';\n  let audioCtx = null;\n  let musicTimer = null, musicStep = 0;\n\n  function clone(v){ return v.map(a=>[...a]); }\n  function serialize(v){ return v.map(a=>a.join(',')).join('|'); }\n  function topColor(i, src=state){ const a=src[i]; return a.length ? a[a.length-1] : null; }\n  function contiguousTop(i, src=state){\n    const a=src[i];\n    if(!a.length) return 0;\n    const c=a[a.length-1];\n    let n=0;\n    for(let k=a.length-1; k>=0 && a[k]===c; k--) n++;\n    return n;\n  }\n  function isDone(i, src=state){\n    const a=src[i];\n    return a.length===GOAL_COUNT && a.every(x=>x===TARGETS[i]);\n  }\n  function canPour(from,to, src=state){\n    if(from===to || !src[from].length || src[to].length>=CAPACITY) return false;\n    return true;\n  }\n  function transferable(from,to, src=state){\n    if(!canPour(from,to,src)) return 0;\n    return Math.min(contiguousTop(from,src), CAPACITY-src[to].length);\n  }\n  function checkWinState(src){\n    return src.every((a,i)=>a.length===GOAL_COUNT && a.every(x=>x===TARGETS[i]));\n  }\n  function shuffleArray(arr){\n    for(let i=arr.length-1;i>0;i--){\n      const j=Math.floor(Math.random()*(i+1));\n      [arr[i],arr[j]]=[arr[j],arr[i]];\n    }\n    return arr;\n  }\n  function goalState(){ return TARGETS.map(c=>Array(GOAL_COUNT).fill(c)); }\n  function getValidMoves(src){\n    const moves=[];\n    for(let from=0; from<src.length; from++){\n      for(let to=0; to<src.length; to++){\n        if(canPour(from,to,src)) moves.push([from,to]);\n      }\n    }\n    return moves;\n  }\n  function generateRound(maxAttempts=80){\n    const pool=TARGETS.flatMap(c=>Array(GOAL_COUNT).fill(c));\n    for(let attempt=0; attempt<maxAttempts; attempt++){\n      const shuffled=shuffleArray([...pool]);\n      const candidate=[];\n      for(let i=0;i<5;i++) candidate.push(shuffled.slice(i*GOAL_COUNT,(i+1)*GOAL_COUNT));\n      if(checkWinState(candidate)) continue;\n      const mixedCount=candidate.filter(t=>new Set(t).size>=2).length;\n      if(mixedCount<4) continue;\n      if(getValidMoves(candidate).length) return candidate;\n    }\n    return [\n      ['yellow','purple','pink','green'],\n      ['red','yellow','purple','pink'],\n      ['green','red','yellow','purple'],\n      ['pink','green','red','yellow'],\n      ['purple','pink','green','red']\n    ];\n  }\n\n  function formatTime(sec){ const m=String(Math.floor(sec/60)).padStart(2,'0'); const s=String(sec%60).padStart(2,'0'); return `${m}:${s}`; }\n  function updateTime(){\n    timeEl.textContent = formatTime(timeLeft);\n    if(timeLeft<=5){\n      timeEl.style.color='#ffe38a';\n      timeEl.style.textShadow='0 0 10px rgba(255,227,138,.55)';\n    }else{\n      timeEl.style.color='';\n      timeEl.style.textShadow='';\n    }\n  }\n  function stopTimer(){ if(timerId){ clearInterval(timerId); timerId = null; } }\n  function tickTock(){ try{ensureAudio(); const now=audioCtx.currentTime; const o=audioCtx.createOscillator(), g=audioCtx.createGain(); o.type='square'; o.frequency.setValueAtTime(1080, now); g.gain.setValueAtTime(.0001, now); g.gain.exponentialRampToValueAtTime(.09, now+.01); g.gain.exponentialRampToValueAtTime(.001, now+.16); o.connect(g).connect(audioCtx.destination); o.start(now); o.stop(now+.17);}catch(e){} }\n  function startTimer(){\n    stopTimer();\n    timerId = setInterval(()=>{\n      if(paused || game.style.display!=='flex' || gameOver) return;\n      if(timeLeft>0){\n        timeLeft--;\n        elapsed++;\n        if(timeLeft<=5 && timeLeft>0){ tickTock(); }\n        updateTime();\n        if(timeLeft<=0){ lose(); }\n      }\n    },1000);\n  }\n  function getRanking(){ try{ return JSON.parse(localStorage.getItem(RANK_KEY)||'[]'); }catch(e){ return []; } }\n  function saveRanking(list){ try{ localStorage.setItem(RANK_KEY, JSON.stringify(list)); }catch(e){} }\n  function refreshRankingHint(){ const top=getRanking()[0]; rankingHint.textContent = top ? `Melhor ${top.moves} mov.` : 'Ver pontuações'; }\n  function renderRanking(){ const list=getRanking(); const el=document.getElementById('rankingList'); if(!list.length){ el.innerHTML='<div class=\"emptyRank\">Ainda não há pontuações registradas.</div>'; refreshRankingHint(); return; } el.innerHTML=list.map((r,i)=>`<div class=\"rankRow\"><span>#${i+1}</span><span>${escapeHtml(r.name||'Jogador')}<br><small>${formatTime(r.time)}</small></span><span>${r.moves} mov.</span></div>`).join(''); refreshRankingHint(); }\n  function addRankingEntry(){ const list=getRanking(); list.push({name:playerName||'Jogador',time:elapsed,moves,date:Date.now()}); list.sort((a,b)=> a.moves-b.moves || a.time-b.time || a.date-b.date); saveRanking(list.slice(0,10)); renderRanking(); }\n  function escapeHtml(v){ return String(v).replace(/[&<>'\"]/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;',\"'\":'&#39;','\"':'&quot;'}[c])); }\n  function askPlayerName(){\n    nameError.textContent='';\n    playerNameInput.value=playerName || '';\n    showModal('nameModal');\n    setTimeout(()=>playerNameInput.focus(),80);\n  }\n  function confirmPlayerName(){\n    const name=playerNameInput.value.trim().replace(/\\s+/g,' ');\n    if(!name){ nameError.textContent='Digite o nome do jogador para iniciar.'; playerNameInput.focus(); return; }\n    playerName=name.slice(0,24);\n    playerBadge.textContent='Jogador: '+playerName;\n    hideModal('nameModal');\n    startGame();\n  }\n  function openRanking(){ if(busy) return; if(game.style.display==='flex' && !gameOver){ paused=true; stopTimer(); stopArcadeMusic(); } renderRanking(); showModal('rankingModal'); clickTone(260,.05); }\n  function closeRanking(){ hideModal('rankingModal'); if(game.style.display==='flex' && !gameOver){ paused=false; startTimer(); startArcadeMusic(); } }\n  function openHelp(){ if(game.style.display==='flex' && !gameOver){ paused=true; stopTimer(); stopArcadeMusic(); } showModal('helpModal'); clickTone(300,.05); }\n  function closeHelp(){ hideModal('helpModal'); if(game.style.display==='flex' && !gameOver){ paused=false; startTimer(); startArcadeMusic(); } }\n\n  function render(){\n    board.innerHTML='';\n    state.forEach((layers,i)=>{\n      const slot=document.createElement('div'); slot.className='slot slot-'+TARGETS[i]+(selected===i?' selected':'')+(isDone(i)?' done':''); slot.dataset.i=i; slot.dataset.target=TARGETS[i]; slot.setAttribute('aria-label','Taça de '+BOTTLE_NAMES[i]+' — objetivo: '+TARGETS[i]);\n      const glass=document.createElement('div'); glass.className='glass'; glass.innerHTML='<div class=\"bowl\"><div class=\"liquidStack\"></div></div><div class=\"stem\"></div><div class=\"base\"></div><div class=\"cork\"></div>';\n      const stack=glass.querySelector('.liquidStack');\n      const unit=(100/CAPACITY).toFixed(4)+'%';\n      layers.forEach(c=>{ const d=document.createElement('div'); d.className='layer '+c; d.style.height=unit; d.style.flex='0 0 '+unit; stack.appendChild(d); });\n      slot.appendChild(glass); board.appendChild(slot);\n      slot.addEventListener('pointerup',()=>tap(i));\n    });\n    movesEl.textContent=moves;\n    if(undoTopBtn){ undoTopBtn.disabled = busy || history.length===0; undoTopBtn.style.opacity = history.length ? '1' : '.45'; }\n    updateTime();\n  }\n\n  function tap(i){\n    if(busy || paused || gameOver || isDone(i) && selected===null) return;\n    if(selected===null){\n      if(!state[i].length) return;\n      selected=i; render(); lift(i,true); clickTone(340,.05); return;\n    }\n    const from=selected;\n    if(i===from){ selected=null; render(); clickTone(220,.04); return; }\n    if(!canPour(from,i)){\n      const bad=document.querySelector('.slot[data-i=\"'+i+'\"]'); if(bad){bad.classList.add('invalid');setTimeout(()=>bad.classList.remove('invalid'),450)}\n      clickTone(120,.08); return;\n    }\n    selected=null;\n    pour(from,i);\n  }\n\n  function lift(i,on){ const el=document.querySelector('.slot[data-i=\"'+i+'\"] .glass'); if(el) el.style.transform=on?'translateX(-50%) translateY(-10px)':'translateX(-50%)'; }\n\n  async function pour(from,to){\n    busy=true;\n    const count=transferable(from,to);\n    const color=topColor(from);\n    history.push({state:clone(state),moves});\n\n    const fromSlot=document.querySelector('.slot[data-i=\"'+from+'\"]');\n    const toSlot=document.querySelector('.slot[data-i=\"'+to+'\"]');\n    const glass=fromSlot.querySelector('.glass');\n    const fr=glass.getBoundingClientRect();\n    const tb=toSlot.querySelector('.bowl').getBoundingClientRect();\n    const fromCenterX = fr.left + fr.width/2;\n    const toCenterX = tb.left + tb.width/2;\n    const dir = toCenterX > fromCenterX ? 1 : -1;\n    const hoverX = (toCenterX - fromCenterX) * 0.92;\n    const hoverY = (tb.top - fr.top) - Math.max(fr.height*0.72, 122);\n    const tiltY = hoverY + 6;\n    const tiltAngle = dir * 70;\n\n    const fly=glass.animate([\n      {transform:'translateX(-50%) translateY(-10px) rotate(0deg)'},\n      {transform:`translateX(calc(-50% + ${hoverX*0.28}px)) translateY(${hoverY*0.40}px) rotate(${dir*3}deg)`,offset:.24},\n      {transform:`translateX(calc(-50% + ${hoverX*0.70}px)) translateY(${hoverY*0.88}px) rotate(${dir*4}deg)`,offset:.66},\n      {transform:`translateX(calc(-50% + ${hoverX}px)) translateY(${hoverY}px) rotate(0deg)`}\n    ],{duration:720,easing:'cubic-bezier(.22,.84,.23,1)',fill:'forwards'});\n    await fly.finished.catch(()=>{});\n\n    const tilt=glass.animate([\n      {transform:`translateX(calc(-50% + ${hoverX}px)) translateY(${hoverY}px) rotate(0deg)`},\n      {transform:`translateX(calc(-50% + ${hoverX}px)) translateY(${tiltY}px) rotate(${tiltAngle}deg)`}\n    ],{duration:240,easing:'ease-out',fill:'forwards'});\n    await tilt.finished.catch(()=>{});\n\n    const finalCenterX = fromCenterX + hoverX;\n    const finalTop = fr.top + tiltY;\n    const spoutX = finalCenterX + dir*(fr.width*0.24);\n    const spoutY = finalTop + fr.height*0.17;\n    const destX = tb.left + tb.width*0.50;\n    const destY = tb.top + Math.max(18, tb.height*0.18);\n    const dx = destX - spoutX;\n    const dy = destY - spoutY;\n    const streamH = Math.max(92, Math.hypot(dx,dy));\n    const streamRot = (Math.atan2(dy,dx) * 180 / Math.PI) - 90;\n    const liquid = COLOR_HEX[color] || '#ffffff';\n    stream.style.left=spoutX+'px';\n    stream.style.top=spoutY+'px';\n    stream.style.width=Math.max(11, fr.width*0.13)+'px';\n    stream.style.background=`linear-gradient(90deg, rgba(255,255,255,.20) 0%, ${liquid} 20%, ${liquid} 76%, rgba(255,255,255,.14) 100%)`;\n    stream.style.height='0px';\n    stream.style.transform=`translateX(-50%) rotate(${streamRot}deg)`;\n    stream.classList.add('on');\n    requestAnimationFrame(()=>stream.style.height=streamH+'px');\n    pourSound(true);\n\n    for(let n=0;n<count;n++){\n      await sleep(260);\n      state[from].pop();\n      state[to].push(color);\n      renderStaticDuringPour(from,to,glass);\n    }\n\n    await sleep(150);\n    renderStaticDuringPour(from,to,glass);\n    stream.style.height='0px';\n    await sleep(120);\n    stream.classList.remove('on');\n    stream.style.transform='translateX(-50%) rotate(0deg)';\n    pourSound(false);\n\n    const untilt=glass.animate([\n      {transform:`translateX(calc(-50% + ${hoverX}px)) translateY(${tiltY}px) rotate(${tiltAngle}deg)`},\n      {transform:`translateX(calc(-50% + ${hoverX}px)) translateY(${hoverY}px) rotate(0deg)`}\n    ],{duration:220,easing:'ease-in-out',fill:'forwards'});\n    await untilt.finished.catch(()=>{});\n\n    const back=glass.animate([\n      {transform:`translateX(calc(-50% + ${hoverX}px)) translateY(${hoverY}px) rotate(0deg)`},\n      {transform:`translateX(calc(-50% + ${hoverX*0.56}px)) translateY(${hoverY*0.74}px) rotate(${dir*2}deg)`,offset:.34},\n      {transform:`translateX(calc(-50% + ${hoverX*0.18}px)) translateY(${hoverY*0.26}px) rotate(${-dir*1}deg)`,offset:.74},\n      {transform:'translateX(-50%) translateY(0) rotate(0deg)'}\n    ],{duration:620,easing:'cubic-bezier(.34,.05,.26,1)',fill:'forwards'});\n    await back.finished.catch(()=>{});\n\n    moves++;\n    busy=false;\n    render();\n    if(gameOver) return;\n    if(isDone(to)){ completionTone(); }\n    if(checkWin()){ setTimeout(win,500); }\n  }\n\n  // Rebuilds liquid stacks while keeping the pouring glass itself in place during the animation.\n  function renderStaticDuringPour(from,to,pouringGlass){\n    const fromStack=pouringGlass.querySelector('.liquidStack');\n    const unit=(100/CAPACITY).toFixed(4)+'%';\n    fromStack.innerHTML=''; state[from].forEach(c=>{const d=document.createElement('div');d.className='layer '+c;d.style.height=unit;d.style.flex='0 0 '+unit;fromStack.appendChild(d)});\n    const t=document.querySelector('.slot[data-i=\"'+to+'\"] .liquidStack');\n    if(t){t.innerHTML='';state[to].forEach(c=>{const d=document.createElement('div');d.className='layer '+c;d.style.height=unit;d.style.flex='0 0 '+unit;t.appendChild(d)});}\n  }\n\n  function checkWin(){ return checkWinState(state); }\n  function undo(){\n    if(busy || paused || gameOver || !history.length) return;\n    const h=history.pop();\n    state=clone(h.state);\n    moves=h.moves;\n    selected=null;\n    busy=false;\n    render();\n    clickTone(260,.07);\n    showToast('Última jogada desfeita.');\n  }\n  function reset(){\n    if(busy)return;\n    initialState=generateRound();\n    state=clone(initialState);\n    history=[];\n    moves=0;\n    elapsed=0;\n    timeLeft=TOTAL_TIME;\n    lastTickWarn=null;\n    selected=null;\n    paused=false;\n    gameOver=false;\n    stopTimer();\n    render();\n    hideModal('pauseModal'); hideModal('helpModal'); hideModal('rankingModal'); hideModal('winModal'); hideModal('loseModal');\n    clickTone(300,.05);\n    if(game.style.display==='flex'){ startTimer(); startArcadeMusic(); }\n  }\n  function win(){\n    if(gameOver) return;\n    gameOver=true;\n    stopTimer();\n    stopArcadeMusic();\n    document.getElementById('finalPlayer').textContent=playerName||'Jogador';\n    document.getElementById('finalMoves').textContent=moves;\n    document.getElementById('finalTime').textContent=formatTime(elapsed);\n    addRankingEntry();\n    showModal('winModal');\n    victorySound();\n  }\n  function lose(){\n    if(gameOver) return;\n    gameOver=true;\n    stopTimer();\n    stopArcadeMusic();\n    timeLeft=0;\n    updateTime();\n    document.getElementById('losePlayer').textContent=playerName||'Jogador';\n    document.getElementById('loseMoves').textContent=moves;\n    document.getElementById('loseTime').textContent=formatTime(elapsed);\n    showModal('loseModal');\n    defeatSound();\n  }\n  function showToast(msg){toast.textContent=msg;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),1300)}\n  function showModal(id){document.getElementById(id).classList.add('show')}\n  function hideModal(id){document.getElementById(id).classList.remove('show')}\n  function sleep(ms){return new Promise(r=>setTimeout(r,ms))}\n\n  function startGame(){ if(!playerName){ askPlayerName(); return; } cover.style.display='none'; game.style.display='flex'; playerBadge.textContent='Jogador: '+playerName; ensureAudio(); reset(); startArcadeMusic(); renderRanking(); showToast('Você tem 2 minutos. Nos 5 segundos finais o tic-tac será ativado.'); }\n  function goHome(){ if(busy)return; stopTimer(); stopArcadeMusic(); game.style.display='none'; cover.style.display='flex'; hideModal('pauseModal'); hideModal('helpModal'); hideModal('rankingModal'); hideModal('winModal'); hideModal('loseModal'); paused=false; gameOver=false; }\n  function togglePause(){ if(busy || gameOver)return; paused=true; stopTimer(); stopArcadeMusic(); showModal('pauseModal'); clickTone(210,.05); }\n\n  function ensureAudio(){ try{ if(!audioCtx) audioCtx=new (window.AudioContext||window.webkitAudioContext)(); if(audioCtx.state==='suspended') audioCtx.resume(); }catch(e){} }\n  function clickTone(freq,dur){try{ensureAudio();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.08,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+dur);o.connect(g).connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+dur)}catch(e){}}\n  function musicNote(freq,dur=.13,vol=.026,type='square'){\n    try{\n      ensureAudio();\n      if(!audioCtx || !freq) return;\n      const now=audioCtx.currentTime;\n      const o=audioCtx.createOscillator(), g=audioCtx.createGain();\n      o.type=type;\n      o.frequency.setValueAtTime(freq,now);\n      g.gain.setValueAtTime(.0001,now);\n      g.gain.exponentialRampToValueAtTime(vol,now+.012);\n      g.gain.exponentialRampToValueAtTime(.001,now+dur);\n      o.connect(g).connect(audioCtx.destination);\n      o.start(now);\n      o.stop(now+dur+.02);\n    }catch(e){}\n  }\n  function startArcadeMusic(){\n    if(musicTimer || paused || gameOver || game.style.display!=='flex') return;\n    ensureAudio();\n    const melody=[523,659,784,659,587,698,880,698,523,659,784,988,880,784,659,587];\n    const bass=[131,131,147,147,165,165,147,147];\n    musicStep=musicStep%melody.length;\n    const playStep=()=>{\n      if(paused || gameOver || game.style.display!=='flex') return;\n      const m=melody[musicStep%melody.length];\n      musicNote(m,.135,.024,'square');\n      if(musicStep%2===0) musicNote(bass[(musicStep/2)%bass.length],.20,.018,'triangle');\n      if(musicStep%4===2) musicNote(m/2,.09,.010,'square');\n      musicStep=(musicStep+1)%melody.length;\n    };\n    playStep();\n    musicTimer=setInterval(playStep,180);\n  }\n  function stopArcadeMusic(){\n    if(musicTimer){ clearInterval(musicTimer); musicTimer=null; }\n  }\n  let noiseNode=null;\n  function pourSound(on){try{ensureAudio(); if(on){\n      const len=audioCtx.sampleRate*.6, buf=audioCtx.createBuffer(1,len,audioCtx.sampleRate), data=buf.getChannelData(0); for(let i=0;i<len;i++) data[i]=(Math.random()*2-1)*.35;\n      const src=audioCtx.createBufferSource(),f=audioCtx.createBiquadFilter(),g=audioCtx.createGain();src.buffer=buf;src.loop=true;f.type='bandpass';f.frequency.value=900;f.Q.value=.5;g.gain.value=.055;src.connect(f).connect(g).connect(audioCtx.destination);src.start();noiseNode=src;\n    } else if(noiseNode){noiseNode.stop();noiseNode=null}\n  }catch(e){}}\n  function completionTone(){try{ensureAudio();[520,660,780].forEach((f,i)=>setTimeout(()=>clickTone(f,.10),i*80))}catch(e){}}\n  function arcadePhrase(notes, dur=.12, type='square'){ try{ ensureAudio(); notes.forEach((f,i)=>{ setTimeout(()=>{ const now=audioCtx.currentTime; const o=audioCtx.createOscillator(), g=audioCtx.createGain(); o.type=type; o.frequency.value=f; g.gain.setValueAtTime(.0001, now); g.gain.exponentialRampToValueAtTime(.09, now+.01); g.gain.exponentialRampToValueAtTime(.001, now+dur); o.connect(g).connect(audioCtx.destination); o.start(now); o.stop(now+dur); }, i*(dur*1000*0.95)); }); }catch(e){} }\n  function victorySound(){ arcadePhrase([523,659,784,988,1175,1319], .16, 'square'); }\n  function defeatSound(){ arcadePhrase([660,622,587,523,466,392,349], .17, 'sawtooth'); }\n\n  function bindTap(id, handler){\n    const el=document.getElementById(id);\n    if(!el) return;\n    let lastFire=0;\n    const fire=(e)=>{\n      const now=Date.now();\n      if(now-lastFire<350) return;\n      lastFire=now;\n      if(e && e.cancelable) e.preventDefault();\n      handler(e);\n    };\n    el.addEventListener('pointerup',fire,{passive:false});\n    el.addEventListener('click',fire,{passive:false});\n  }\n\n  bindTap('startHotspot',askPlayerName);\n  bindTap('rankingHotspot',openRanking);\n  bindTap('howHotspot',openHelp);\n  bindTap('confirmNameBtn',confirmPlayerName);\n  bindTap('cancelNameBtn',()=>{hideModal('nameModal');nameError.textContent=''});\n  if(playerNameInput) playerNameInput.addEventListener('keydown',e=>{if(e.key==='Enter')confirmPlayerName()});\n  if(undoTopBtn) bindTap('undoTopBtn',undo);\n  bindTap('pauseBtn',togglePause);\n  bindTap('rankingBtn',openRanking);\n  bindTap('resumeBtn',()=>{paused=false;hideModal('pauseModal');startTimer();startArcadeMusic()});\n  bindTap('pauseResetBtn',reset);\n  bindTap('pauseHomeBtn',goHome);\n  bindTap('closeHelpBtn',closeHelp);\n  bindTap('closeRankingBtn',closeRanking);\n  bindTap('clearRankingBtn',()=>{saveRanking([]);renderRanking()});\n  bindTap('playAgainBtn',()=>{hideModal('winModal');reset()});\n  bindTap('winHomeBtn',goHome);\n  bindTap('loseAgainBtn',()=>{hideModal('loseModal');reset()});\n  bindTap('loseHomeBtn',goHome);\n\n  initialState=goalState();\n  state=clone(initialState);\n  renderRanking();\n  render();\n})();\n</script>\n</body>\n</html>");